body.script:
//
function vipMedStep1Validate(){
  var valid=true;
  function showErr(id,msg){var el=document.getElementById(id);if(!el){el=document.createElement("div");el.id=id;el.style.cssText="color:red;font-size:12px;margin-top:4px";}el.textContent=msg;el.style.display="block";}
  function hideErr(id){var el=document.getElementById(id);if(el)el.style.display="none";}
  function addErr(field,id){if(!document.getElementById(id)){var e=document.createElement("div");e.id=id;e.style.cssText="color:red;font-size:12px;margin-top:4px";field.insertAdjacentElement("afterend",e);}}

  var asel=document.querySelector('[name="applicant_select"]');
  var aname=document.querySelector('[name="applicant_name"]');
  var aselv=asel?asel.value.trim():"";
  var anamev=aname?aname.value.trim():"";
  if(!aselv&amp;&amp;anamev.length&lt;3){addErr(aname,"ap_err");showErr("ap_err","Please select an applicant or enter name (min 3 characters).");valid=false;}else hideErr("ap_err");

  var fn=document.querySelector('[name="first_name"]');addErr(fn,"fn_err");
  if(!fn||fn.value.trim().length&lt;3||fn.value.trim().length&gt;50){showErr("fn_err","First name must be 3-50 characters.");valid=false;}else hideErr("fn_err");

  var ln=document.querySelector('[name="last_name"]');addErr(ln,"ln_err");
  if(!ln||ln.value.trim().length&lt;3||ln.value.trim().length&gt;50){showErr("ln_err","Last name must be 3-50 characters.");valid=false;}else hideErr("ln_err");

  var ph=document.querySelector('[name="contact_number"]');addErr(ph,"ph_err");
  var phv=ph?ph.value.trim().replace(/\D/g,""):"";
  if(phv.length&lt;10||phv.length&gt;20){showErr("ph_err","Contact number must be 10-20 digits.");valid=false;}else hideErr("ph_err");

  var em=document.querySelector('[name="email"]');addErr(em,"em_err");
  var emv=em?em.value.trim():"";
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emv)){showErr("em_err","Please enter a valid email address.");valid=false;}else hideErr("em_err");

  var pd=document.querySelector('[name="preferred_date"]');addErr(pd,"pd_err");
  if(!pd||!pd.value){showErr("pd_err","Please select a preferred date.");valid=false;}else hideErr("pd_err");

  var bv=document.querySelector('[name="building_villa"]');addErr(bv,"bv_err");
  if(!bv||bv.value.trim().length&lt;3||bv.value.trim().length&gt;50){showErr("bv_err","Building/Villa must be 3-50 characters.");valid=false;}else hideErr("bv_err");

  var ct=document.querySelector('[name="city"]');
  if(!document.getElementById("ct_err")){var e=document.createElement("div");e.id="ct_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";ct.parentElement.insertAdjacentElement("afterend",e);}
  if(!ct||!ct.value){showErr("ct_err","Please select a city.");valid=false;}else hideErr("ct_err");

  var lm=document.querySelector('[name="nearest_landmark"]');addErr(lm,"lm_err");
  if(!lm||lm.value.trim().length&lt;3||lm.value.trim().length&gt;50){showErr("lm_err","Landmark must be 3-50 characters.");valid=false;}else hideErr("lm_err");

  if(valid)document.querySelector("form").submit();
}
//

//
function showName(i,l){if(i.files&amp;&amp;i.files[0])document.getElementById(l).textContent=i.files[0].name;}
function vipMedStep2Validate(){
  var valid=true;
  var p=document.getElementById("passport_photo");if(!p||p.files.length===0){if(!document.getElementById("ph2_err")){var e=document.createElement("div");e.id="ph2_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";p.closest(".upload-box").insertAdjacentElement("afterend",e);}document.getElementById("ph2_err").textContent="Please upload passport-sized photo.";document.getElementById("ph2_err").style.display="block";valid=false;}else{var pe=document.getElementById("ph2_err");if(pe)pe.style.display="none";}
  var v=document.getElementById("entry_visa");if(!v||v.files.length===0){if(!document.getElementById("ev_err")){var e=document.createElement("div");e.id="ev_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";v.closest(".upload-box").insertAdjacentElement("afterend",e);}document.getElementById("ev_err").textContent="Please upload entry visa document.";document.getElementById("ev_err").style.display="block";valid=false;}else{var ve=document.getElementById("ev_err");if(ve)ve.style.display="none";}
  if(valid)document.querySelector("form").submit();
}
//

function csValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var lic = document.getElementById('lic_manual');
  var licv = lic ? lic.value.trim() : '';
  if (licv.length &lt; 5 || licv.length &gt; 15 || !/^[A-Za-z0-9]+$/.test(licv)) {
    showErr('lic_err','License number must be 5-15 alphanumeric characters.'); valid=false;
  } else hideErr('lic_err');
  var cn = document.querySelector('[name="company_name"]');
  var cnv = cn ? cn.value.trim() : '';
  if (cnv.length &lt; 3 || cnv.length &gt; 50) {
    showErr('cname_err','Company name must be 3-50 characters.'); valid=false;
  } else hideErr('cname_err');
  if (valid) document.querySelector('form').submit();
}

function csValidateStep2() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var terms = document.getElementById('termsCheck');
  if (!terms || !terms.checked) { showErr('terms_err','Please agree to the declaration to proceed.'); valid=false; } else hideErr('terms_err');
  if (valid) document.querySelector('form').submit();
}

function toggleSpcVisa(v){
    document.getElementById('no_spc_msg').classList.toggle('hidden',v!=='no');
    document.getElementById('visa_fields_wrap').classList.toggle('hidden',v!=='yes');
}
function toggleType(v){
    var ef = document.getElementById('employee_fields');
    var iif = document.getElementById('investor_fields');
    var sw = document.getElementById('salary_wrap');
    var dw = document.getElementById('desig_wrap');
    var mw = document.getElementById('marital_wrap');
    if(ef) ef.classList.toggle('hidden',v!=='employee');
    if(iif) iif.classList.toggle('hidden',v!=='investor');
    if(sw) sw.classList.toggle('hidden',v!=='employee');
    if(dw) dw.classList.toggle('hidden',v!=='employee');
    if(mw) mw.classList.remove('hidden');
}
function toggleGender(v){
    var mw = document.getElementById('marital_wrap');
    if(mw) mw.classList.remove('hidden');
}
function showName(i,l){if(i.files&amp;&amp;i.files[0])document.getElementById(l).textContent=i.files[0].name;}
function dvValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  function radioVal(name) { var r=document.querySelector('[name="'+name+'"]:checked'); return r?r.value:''; }

  if (!radioVal('sponsor_has_spc_visa')) { showErr('spc_visa_err','Please select an option.'); valid=false; } else hideErr('spc_visa_err');

  var spcVisa = radioVal('sponsor_has_spc_visa');
  if (spcVisa === 'yes') {
    if (!radioVal('sponsor_type')) { showErr('sponsor_type_err','Please select Employee or Investor.'); valid=false; } else hideErr('sponsor_type_err');
    if (!radioVal('sponsor_gender')) { showErr('gender_err','Please select a gender.'); valid=false; } else hideErr('gender_err');

    var fn = document.querySelector('[name="sponsor_first_name"]');
    var fnv = fn ? fn.value.trim() : '';
    if (fnv.length &lt; 2 || fnv.length &gt; 50 || !/^[A-Za-z ]+$/.test(fnv)) { showErr('sfn_err','First name must be 2-50 characters (letters only).'); valid=false; } else hideErr('sfn_err');

    var ln = document.querySelector('[name="sponsor_last_name"]');
    var lnv = ln ? ln.value.trim() : '';
    if (lnv.length &lt; 2 || lnv.length &gt; 50 || !/^[A-Za-z ]+$/.test(lnv)) { showErr('sln_err','Last name must be 2-50 characters (letters only).'); valid=false; } else hideErr('sln_err');

    var sType = radioVal('sponsor_type');
    if (sType === 'employee') {
      var sal = document.querySelector('[name="salary"]');
      var salv = sal ? sal.value.trim() : '';
      if (salv.length &gt; 50) { showErr('salary_err','Salary must be 0-50 characters.'); valid=false; } else hideErr('salary_err');
      var desig = document.querySelector('[name="designation"]');
      if (!desig || !desig.value) { showErr('desig_err','Please select a designation.'); valid=false; } else hideErr('desig_err');
    }

    if (!radioVal('sponsor_marital_status')) { showErr('marital_err','Please select a marital status.'); valid=false; } else hideErr('marital_err');
    if (!radioVal('tenancy_under_sponsor')) { showErr('tenancy_err','Please select an option.'); valid=false; } else hideErr('tenancy_err');

    var files = [
      ['passport_copy','passport_file_err','Passport copy is required.'],
      ['residence_visa','res_visa_file_err','Residence visa copy is required.'],
      ['emirates_id','eid_file_err','Emirates ID copy is required.'],
      ['tenancy_contract','tenancy_file_err','Attested tenancy contract is required.'],
      ['utility_bill','utility_file_err','Utility bill copy is required.'],
    ];
    files.forEach(function(f) {
      var el = document.getElementById(f[0]);
      if (!el || !el.files || el.files.length === 0) { showErr(f[1], f[2]); valid=false; } else hideErr(f[1]);
    });
  }

  if (valid) document.querySelector('form').submit();
}

function showName(i,l){if(i.files&amp;&amp;i.files[0])document.getElementById(l).textContent=i.files[0].name;}
function dvValidateStep2() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var dfn = document.querySelector('[name="dep_first_name"]');
  var dfnv = dfn ? dfn.value.trim() : '';
  if (dfnv.length &lt; 2 || dfnv.length &gt; 50 || !/^[A-Za-z ]+$/.test(dfnv)) { showErr('dfn_err','First name must be 2-50 characters.'); valid=false; } else hideErr('dfn_err');
  var dln = document.querySelector('[name="dep_last_name"]');
  var dlnv = dln ? dln.value.trim() : '';
  if (dlnv.length &lt; 2 || dlnv.length &gt; 50 || !/^[A-Za-z ]+$/.test(dlnv)) { showErr('dln_err','Last name must be 2-50 characters.'); valid=false; } else hideErr('dln_err');
  var dfath = document.querySelector('[name="dep_father_name"]');
  var dfathv = dfath ? dfath.value.trim() : '';
  if (dfathv.length &lt; 2 || dfathv.length &gt; 50 || !/^[A-Za-z ]+$/.test(dfathv)) { showErr('dfath_err',"Father name must be 2-50 characters."); valid=false; } else hideErr('dfath_err');
  var dmoth = document.querySelector('[name="dep_mother_name"]');
  var dmothv = dmoth ? dmoth.value.trim() : '';
  if (dmothv.length &lt; 2 || dmothv.length &gt; 50 || !/^[A-Za-z ]+$/.test(dmothv)) { showErr('dmoth_err',"Mother name must be 2-50 characters."); valid=false; } else hideErr('dmoth_err');
  var dmob = document.querySelector('[name="dep_mobile"]');
  var dmobv = dmob ? dmob.value.trim() : '';
  if (dmobv.length &lt; 10 || dmobv.length &gt; 15 || !/^[0-9]+$/.test(dmobv)) { showErr('dmob_err','Phone must be 10-15 digits.'); valid=false; } else hideErr('dmob_err');
  var selects = [
    ['dep_nationality','dnat_err','Please select nationality.'],
    ['dep_prev_nationality','dpnat_err','Please select previous nationality.'],
    ['dep_marital_status','dmar_err','Please select marital status.'],
    ['dep_religion','drel_err','Please select religion.'],
  ];
  selects.forEach(function(s) {
    var el = document.querySelector('[name="'+s[0]+'"]');
    if (!el || !el.value) { showErr(s[1], s[2]); valid=false; } else hideErr(s[1]);
  });
  var files = [
    ['dep_passport','dep_passport_err','Passport copy is required.'],
    ['dep_photo','dep_photo_err','High resolution photo is required.'],
    ['dep_passport_special','dep_passport_sp_err','Passport special page is required.'],
    ['dep_noc','dep_noc_err','Attested NOC from father is required.'],
  ];
  files.forEach(function(f) {
    var el = document.getElementById(f[0]);
    if (!el || !el.files || el.files.length === 0) { showErr(f[1], f[2]); valid=false; } else hideErr(f[1]);
  });
  if (valid) document.querySelector('form').submit();
}

function showName(i,l){if(i.files&amp;&amp;i.files[0])document.getElementById(l).textContent=i.files[0].name;}
function toggleLocation(v){
    var inf = document.getElementById('inside_fields');
    if(inf) inf.classList.toggle('hidden', v !== 'inside');
}
function toggleStatus(v){
    var cf = document.getElementById('cancelled_visa_doc');
    var vf = document.getElementById('valid_visa_doc');
    if(cf) cf.classList.toggle('hidden', v !== 'cancelled_resident');
    if(vf) vf.classList.toggle('hidden', v !== 'valid_visa');
}
function dvValidateStep3() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  function radioVal(name) { var r=document.querySelector('[name="'+name+'"]:checked'); return r?r.value:''; }

  var loc = radioVal('applicant_location');
  if (!loc) { showErr('loc_err','Please select applicant location.'); valid=false; } else hideErr('loc_err');

  if (loc === 'inside') {
    var status = radioVal('current_status');
    if (!status) { showErr('status_err','Please select applicant current status.'); valid=false; } else hideErr('status_err');

    if (status === 'cancelled_resident') {
      var cvf = document.getElementById('cancelled_visa_file');
      if (!cvf || !cvf.files || cvf.files.length === 0) { showErr('cancelled_visa_err','Cancelled resident visa document is required.'); valid=false; } else hideErr('cancelled_visa_err');
    }
    if (status === 'valid_visa') {
      var vvf = document.getElementById('valid_visa_file');
      if (!vvf || !vvf.files || vvf.files.length === 0) { showErr('valid_visa_err','Valid visa document is required.'); valid=false; } else hideErr('valid_visa_err');
    }
  }

  if (!radioVal('change_of_status')) { showErr('cos_err','Please select if change of status is required.'); valid=false; } else hideErr('cos_err');

  if (valid) document.querySelector('form').submit();
}

function showName(i,l){if(i.files&amp;&amp;i.files[0])document.getElementById(l).textContent=i.files[0].name;}
function dvValidateStep4() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  var ai = document.querySelector('[name="additional_info"]');
  var aiv = ai ? ai.value.trim() : '';
  if (aiv.length &lt; 4 || aiv.length &gt; 100 || !/^[A-Za-z0-9 .,\-]+$/.test(aiv)) { showErr('addinfo_err','Must be 4-100 characters (letters and numbers only).'); valid=false; } else hideErr('addinfo_err');

  var crm = document.querySelector('[name="crm_comments"]');
  var crmv = crm ? crm.value.trim() : '';
  if (crmv.length &lt; 4 || crmv.length &gt; 100 || !/^[A-Za-z0-9 .,\-]+$/.test(crmv)) { showErr('crm_err','Must be 4-100 characters (letters and numbers only).'); valid=false; } else hideErr('crm_err');

  var rd = document.getElementById('remark_doc');
  if (!rd || !rd.files || rd.files.length === 0) { showErr('remark_doc_err','Document upload is required.'); valid=false; } else hideErr('remark_doc_err');

  if (valid) document.querySelector('form').submit();
}

function dvValidateStep5() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }
  var terms = document.getElementById('depTermsCheck');
  if (!terms || !terms.checked) { showErr('dep_terms_err','Please agree to the terms and conditions.'); valid=false; } else hideErr('dep_terms_err');
  if (valid) document.querySelector('form[action*="step5/submit"]').submit();
}

function ddValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  var cdate = document.querySelector('[name="collection_date"]');
  if (!cdate || !cdate.value) { showErr('cdate_err','Please select a valid collection date.'); valid=false; } else hideErr('cdate_err');

  var ctime = document.querySelector('[name="collection_time_frame"]');
  if (!ctime || !ctime.value) { showErr('ctime_err','Please enter a valid collection time.'); valid=false; } else hideErr('ctime_err');

  var caddr = document.querySelector('[name="collection_address"]');
  var caddrv = caddr ? caddr.value.trim() : '';
  if (caddrv.length < 10 || caddrv.length > 100 || !/^[A-Za-z0-9 .,\-]+$/.test(caddrv)) { showErr('caddr_err','Address must be 10-100 characters.'); valid=false; } else hideErr('caddr_err');

  var ddate = document.querySelector('[name="delivery_date"]');
  if (!ddate || !ddate.value) { showErr('ddate_err','Please select a valid delivery date.'); valid=false; } else hideErr('ddate_err');

  var dtime = document.querySelector('[name="delivery_time_frame"]');
  if (!dtime || !dtime.value) { showErr('dtime_err','Please enter a valid delivery time.'); valid=false; } else hideErr('dtime_err');

  var daddr = document.querySelector('[name="delivery_address"]');
  var daddrv = daddr ? daddr.value.trim() : '';
  if (daddrv.length < 10 || daddrv.length > 100 || !/^[A-Za-z0-9 .,\-]+$/.test(daddrv)) { showErr('daddr_err','Address must be 10-100 characters.'); valid=false; } else hideErr('daddr_err');

  if (valid) document.querySelector('form').submit();
}

function ddValidateDecl() {
  var chk = document.getElementById('termsCheck');
  var err = document.getElementById('terms_err');
  if (!chk || !chk.checked) {
    if (err) err.style.display = 'block';
    return;
  }
  if (err) err.style.display = 'none';
  document.querySelector('form').submit();
}

function ddcValidateStep1() {
  var valid = true;
  function showErr(id, msg) { var el=document.getElementById(id); if(el){el.textContent=msg;el.style.display='block';} }
  function hideErr(id) { var el=document.getElementById(id); if(el) el.style.display='none'; }

  var cdate = document.querySelector('[name="collection_date"]');
  if (!cdate || !cdate.value) { showErr('cdate_err','Please select a valid collection date.'); valid=false; } else hideErr('cdate_err');

  var ctime = document.querySelector('[name="collection_time_frame"]');
  if (!ctime || !ctime.value) { showErr('ctime_err','Please enter a valid collection time.'); valid=false; } else hideErr('ctime_err');

  var caddr = document.querySelector('[name="collection_address"]');
  var caddrv = caddr ? caddr.value.trim() : '';
  if (caddrv.length < 10 || caddrv.length > 100) { showErr('caddr_err','Address must be 10-100 characters.'); valid=false; } else hideErr('caddr_err');

  var ddate = document.querySelector('[name="delivery_date"]');
  if (!ddate || !ddate.value) { showErr('ddate_err','Please select a valid delivery date.'); valid=false; } else hideErr('ddate_err');

  var dtime = document.querySelector('[name="delivery_time_frame"]');
  if (!dtime || !dtime.value) { showErr('dtime_err','Please enter a valid delivery time.'); valid=false; } else hideErr('dtime_err');

  var daddr = document.querySelector('[name="delivery_address"]');
  var daddrv = daddr ? daddr.value.trim() : '';
  if (daddrv.length < 10 || daddrv.length > 100) { showErr('daddr_err','Address must be 10-100 characters.'); valid=false; } else hideErr('daddr_err');

  if (valid) document.querySelector('form').submit();
}

function selectStd(v, el) {
    document.querySelectorAll('.delivery-option').forEach(function(d){ d.style.borderColor='#e5e7eb'; d.style.background='white'; });
    el.style.borderColor = '#1abc9c';
    el.style.background = '#f0fdf4';
    document.getElementById('std_'+v).checked = true;
    var show = ['collection_section','delivery_section','remarks_section'];
    show.forEach(function(id){ document.getElementById(id).classList.remove('hidden'); });
    document.getElementById('total_amt').textContent = v === 'local' ? '40.00' : '510.00';
}
// Auto-restore if back navigation
window.addEventListener('DOMContentLoaded', function(){
    var checked = document.querySelector('input[name=delivery_standard]:checked');
    if(checked) selectStd(checked.value, checked.closest('.delivery-option'));
});

function ddcValidateDecl() {
  var chk = document.getElementById('termsCheck');
  var err = document.getElementById('terms_err');
  if (!chk || !chk.checked) {
    if (err) err.style.display = 'block';
    return;
  }
  if (err) err.style.display = 'none';
  document.querySelector('form').submit();
}

