  var valid=true;
  var p=document.getElementById("passport_photo");if(!p||p.files.length===0){if(!document.getElementById("ph2_err")){var e=document.createElement("div");e.id="ph2_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";p.closest(".upload-box").insertAdjacentElement("afterend",e);}document.getElementById("ph2_err").textContent="Please upload passport-sized photo.";document.getElementById("ph2_err").style.display="block";valid=false;}else{var pe=document.getElementById("ph2_err");if(pe)pe.style.display="none";}
  var v=document.getElementById("entry_visa");if(!v||v.files.length===0){if(!document.getElementById("ev_err")){var e=document.createElement("div");e.id="ev_err";e.style.cssText="color:red;font-size:12px;margin-top:4px";v.closest(".upload-box").insertAdjacentElement("afterend",e);}document.getElementById("ev_err").textContent="Please upload entry visa document.";document.getElementById("ev_err").style.display="block";valid=false;}else{var ve=document.getElementById("ev_err");if(ve)ve.style.display="none";}
  if(valid)document.querySelector("form").submit();
